module TopModule (
    input  wire clk,
    input  wire reset,
    input  wire data,
    output reg  start_shifting
);

    typedef enum logic [2:0] {
        S_IDLE = 3'b000,
        S_1    = 3'b001,
        S_11   = 3'b010,
        S_110  = 3'b011,
        S_FOUND= 3'b100
    } state_t;

    state_t state, next_state;

    always_ff @(posedge clk) begin
        if (reset) begin
            state <= S_IDLE;
            start_shifting <= 1'b0;
        end else begin
            state <= next_state;
            if (next_state == S_FOUND || state == S_FOUND)
                start_shifting <= 1'b1;
            else
                start_shifting <= 1'b0;
        end
    end

    always_comb begin
        next_state = state;
        case (state)
            S_IDLE: begin
                if (data) next_state = S_1;
                else      next_state = S_IDLE;
            end
            S_1: begin
                if (data) next_state = S_11;
                else      next_state = S_IDLE;
            end
            S_11: begin
                if (data) next_state = S_11;
                else      next_state = S_110;
            end
            S_110: begin
                if (data) next_state = S_FOUND;
                else      next_state = S_IDLE;
            end
            S_FOUND: begin
                next_state = S_FOUND;
            end
            default: begin
                next_state = S_IDLE;
            end
        endcase
    end

endmodule

