module tb_TopModule;
    reg clk;
    reg reset;
    reg data;
    wire start_shifting;

    TopModule uut (
        .clk(clk),
        .reset(reset),
        .data(data),
        .start_shifting(start_shifting)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        reset = 1;
        data = 0;
        #12;
        reset = 0;

        // Test sequence 1: 1, 1, 0, 1 -> should assert start_shifting
        @(posedge clk); data = 1;
        @(posedge clk); data = 1;
        @(posedge clk); data = 0;
        @(posedge clk); data = 1;

        @(posedge clk);
        if (start_shifting !== 1'b1) begin
            $display("SELFFAIL: Expected start_shifting to be 1 after 1101");
            $finish;
        end

        // Check if it stays 1 forever even with other data
        @(posedge clk); data = 0;
        @(posedge clk); data = 1;
        @(posedge clk);
        if (start_shifting !== 1'b1) begin
            $display("SELFFAIL: start_shifting dropped after being set");
            $finish;
        end

        // Test reset
        reset = 1;
        @(posedge clk);
        reset = 0;
        if (start_shifting !== 1'b0) begin
            $display("SELFFAIL: start_shifting did not clear on reset");
            $finish;
        end

        // Test another sequence with prefix: 1, 1, 1, 0, 1
        @(posedge clk); data = 1;
        @(posedge clk); data = 1;
        @(posedge clk); data = 1;
        @(posedge clk); data = 0;
        @(posedge clk); data = 1;

        @(posedge clk);
        if (start_shifting !== 1'b1) begin
            $display("SELFFAIL: Expected start_shifting to be 1 after 11101");
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

