        // 1
        @(posedge clk); data = 1;
        // 0
        @(posedge clk); data = 0;
        // 1
        @(posedge clk); data = 1;

        // Wait one more cycle for output to reflect
        @(posedge clk);
        #1;
        $display("At time %0t: start_shifting = %b", $time, start_shifting);
        if (start_shifting !== 1'b1) begin
            $display("SELFTEST FAIL: Expected start_shifting to be 1 after 1101");
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

module tb_TopModule;
    reg clk;
    reg reset;
    reg data;
    wire start_shifting;

    TopModule uut (
        .clk(clk),
        .reset(reset),
        .data(data),
        .start_shifting(start_shifting)
    );

    always #5 clk = ~clk;

    task apply_bit(input b);
        begin
            @(posedge clk);
            data = b;
        end
    endtask

    initial begin
        clk = 0;
        reset = 1;
        data = 0;
        #12;
        reset = 0;

        // Feed 0 1 0 1 1 0 1
        apply_bit(0);
        apply_bit(1);
        apply_bit(0);
        apply_bit(1);
        apply_bit(1);
        apply_bit(0);
        apply_bit(1); // 1101 completes here

        @(posedge clk);
        #1;
        if (start_shifting !== 1'b1) begin
            $display("SELFTEST FAIL: 1101 not detected");
            $finish;
        end

        // Check if start_shifting stays high
        apply_bit(0);
        #1;
        if (start_shifting !== 1'b1) begin
            $display("SELFTEST FAIL: start_shifting did not stay high");
            $finish;
        end

        // Test reset
        @(posedge clk);
        reset = 1;
        @(posedge clk);
        reset = 0;
        #1;
        if (start_shifting !== 1'b0) begin
            $display("SELFTEST FAIL: reset did not clear start_shifting");
            $finish;
        end

        // Test another sequence: 1 1 1 0 1
        apply_bit(1);
        apply_bit(1);
        apply_bit(1);
        apply_bit(0);
        apply_bit(1);

        @(posedge clk);
        #1;
        if (start_shifting !== 1'b1) begin
            $display("SELFTEST FAIL: 11101 not detected");
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
